// Nunca deixa $input vazio quebrar o node (SELECT pode nao retornar linha
// nenhuma se a chave "mercadolivre_cookie" nao existir na tabela config).
// O valor do cookie NUNCA e exposto no resultado -- so usamos internamente.

const items = $input.all();
const row = items.length > 0 ? items[0].json : null;
const cookie = row && row.valor ? String(row.valor).trim() : '';

return [{ json: { cookieValido: !!cookie } }];

// Resumo claro de execucao abortada -- nenhuma oferta foi tocada.
console.log('[MONITORAMENTO DE PRECO] Cookie nao configurado; nenhuma oferta foi alterada.');

return [{
  json: {
    status: 'abortado',
    motivo: 'Cookie do Mercado Livre nao configurado (tabela config, chave=mercadolivre_cookie). Nenhuma oferta foi alterada.',
    executadoEm: new Date().toISOString(),
  }
}];

// Zera os contadores do relatorio final no inicio de cada execucao.
const stats = $getWorkflowStaticData('global');
stats.totalVerificado = 0;
stats.semAlteracao = 0;
stats.precosAtualizados = 0;
stats.indisponiveis = 0;
stats.revisaoManual = 0;
stats.falhasTemporarias = 0;
stats.alertasAtingidos = 0;
stats.detalhes = [];
return [{ json: { ok: true } }];

// Resumo seguro da execucao -- nunca inclui cookie ou dados sensiveis.
const stats = $getWorkflowStaticData('global');

const resumo = {
  totalVerificado: stats.totalVerificado || 0,
  semAlteracao: stats.semAlteracao || 0,
  precosAtualizados: stats.precosAtualizados || 0,
  indisponiveis: stats.indisponiveis || 0,
  revisaoManual: stats.revisaoManual || 0,
  falhasTemporarias: stats.falhasTemporarias || 0,
  alertasAtingidos: stats.alertasAtingidos || 0,
  detalhes: stats.detalhes || [],
  executadoEm: new Date().toISOString(),
};

console.log('[MONITORAMENTO DE PRECO] Resumo da execucao:', JSON.stringify(resumo));

return [{ json: resumo }];

// PROCESSA RESPOSTA (v6) — preço confirmado no bloco principal do PDP.
// Suporta catálogo e páginas de variação (_JM). Parcelas, recomendações,
// faixas de preço e JSON-LD isolado nunca atualizam o banco.

const PARSER_VERSION = 'n8n-v6-pdp-variacoes-confirmadas';
const original = $('LOOP PRODUTOS').item.json;
const http = $input.first().json;
const stats = $getWorkflowStaticData('global');

const clean = (value) => String(value || '')
  .replace(/&amp;/g, '&').replace(/&nbsp;/g, ' ')
  .replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();

const normalize = (value) => clean(value).toLowerCase()
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .replace(/[^a-z0-9 ]/g, ' ').replace(/\s+/g, ' ').trim();

const similarity = (a, b) => {
  const left = new Set(normalize(a).split(' ').filter((word) => word.length > 2));
  const right = new Set(normalize(b).split(' ').filter((word) => word.length > 2));
  if (!left.size || !right.size) return 0;
  let same = 0;
  left.forEach((word) => { if (right.has(word)) same += 1; });
  return same / new Set([...left, ...right]).size;
};

const attr = (tag, name) => {
  const escaped = name.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const match = String(tag || '').match(new RegExp(`\\b${escaped}\\s*=\\s*["']([^"']*)["']`, 'i'));
  return match ? match[1] : null;
};

const parseNumber = (value) => {
  if (value === null || value === undefined) return null;
  let text = String(value).trim().replace(/[^\d.,]/g, '');
  if (!text) return null;
  if (text.includes(',') && text.includes('.')) text = text.replace(/\./g, '').replace(',', '.');
  else if (text.includes(',')) text = text.replace(',', '.');
  const number = Number.parseFloat(text);
  return Number.isFinite(number) && number > 0 ? number : null;
};

const parseAriaMoney = (value) => {
  const text = String(value || '').toLowerCase();
  const reais = text.match(/(\d[\d.]*)\s*reais?/i);
  if (!reais) return parseNumber(text);
  const cents = text.match(/(\d{1,2})\s*centavos?/i);
  const whole = reais[1].replace(/\./g, '');
  return Number(`${whole}.${cents ? cents[1].padStart(2, '0') : '00'}`);
};

const parseAndesMoney = (fragment) => {
  const fraction = String(fragment || '').match(/andes-money-amount__fraction[^>]*>([^<]+)</i);
  if (!fraction) return null;
  const cents = String(fragment).match(/andes-money-amount__cents[^>]*>([^<]+)</i);
  const whole = String(fraction[1]).replace(/\D/g, '');
  const decimal = cents ? String(cents[1]).replace(/\D/g, '').padEnd(2, '0').slice(0, 2) : '00';
  return whole ? Number(`${whole}.${decimal}`) : null;
};

// Extrai um elemento HTML completo contando tags aninhadas. Evita ler preços
// que aparecem depois do bloco principal, como parcelas ou recomendações.
const extractElement = (html, startIndex) => {
  const source = String(html || '');
  const openEnd = source.indexOf('>', startIndex);
  if (openEnd < 0) return '';
  const openTag = source.slice(startIndex, openEnd + 1);
  const tagName = (openTag.match(/^<\s*([a-z0-9-]+)/i) || [])[1];
  if (!tagName) return '';
  const matcher = new RegExp(`<\\/?${tagName}\\b[^>]*>`, 'gi');
  matcher.lastIndex = startIndex;
  let depth = 0;
  let match;
  while ((match = matcher.exec(source))) {
    if (/^<\//.test(match[0])) depth -= 1;
    else if (!/\/>$/.test(match[0])) depth += 1;
    if (depth === 0) return source.slice(startIndex, matcher.lastIndex);
  }
  return source.slice(startIndex, Math.min(source.length, startIndex + 16000));
};

const findElementBy = (html, pattern) => {
  const match = String(html || '').match(pattern);
  return match && Number.isInteger(match.index) ? extractElement(html, match.index) : '';
};

const getMetaPrice = (block) => {
  const tags = String(block || '').match(/<meta\b[^>]*>/gi) || [];
  for (const tag of tags) {
    if (String(attr(tag, 'itemprop')).toLowerCase() === 'price') {
      const value = parseNumber(attr(tag, 'content'));
      if (value) return value;
    }
  }
  return null;
};

const getOfferAriaPrice = (block) => {
  const tags = String(block || '').match(/<span\b[^>]*>/gi) || [];
  for (const tag of tags) {
    if (String(attr(tag, 'itemprop')).toLowerCase() === 'offers') {
      const value = parseAriaMoney(attr(tag, 'aria-label'));
      if (value) return value;
    }
  }
  return null;
};

const route = (fields) => {
  const result = {
    offer_id: original.offer_id,
    product_id: original.product_id,
    external_product_id: original.external_product_id,
    product_title: original.product_title,
    public_url: original.public_url,
    precoAntigo: original.current_price == null ? null : Number(original.current_price),
    precoOriginalAntigo: original.original_price == null ? null : Number(original.original_price),
    parserVersion: PARSER_VERSION,
    ...fields,
  };
  stats.totalVerificado = (stats.totalVerificado || 0) + 1;
  stats.detalhes = stats.detalhes || [];
  stats.detalhes.push({
    produto: result.product_title,
    url: result.public_url,
    precoSalvo: result.precoAntigo,
    precoDetectado: result.detectedCurrentPrice ?? null,
    precoOriginalDetectado: result.detectedOriginalPrice ?? null,
    fonte: result.priceSource ?? null,
    rota: result.rota,
    motivo: result.motivo ?? null,
  });
  return [{ json: result }];
};

const statusCode = Number(http.statusCode || 200);
const html = typeof (http.body ?? http.data) === 'string' ? (http.body ?? http.data) : '';

if (http.error || !html || html.length < 500) {
  return route({ rota: 'falha_temporaria', outcome: 'error', httpStatus: statusCode, motivo: 'HTML vazio, incompleto ou erro de rede' });
}
if (statusCode === 404) {
  return route({ rota: 'indisponivel', outcome: 'unavailable', httpStatus: statusCode, motivo: 'Página retornou HTTP 404' });
}
if (statusCode < 200 || statusCode >= 300 || /captcha|perimeterx|g-recaptcha|verificação de segurança|just a moment/i.test(html)) {
  return route({ rota: 'falha_temporaria', outcome: 'error', httpStatus: statusCode, motivo: statusCode === 403 ? 'HTTP 403/CAPTCHA' : 'Resposta HTTP inesperada ou desafio de segurança' });
}

// Catálogo e variação usam wrappers diferentes. Lê o H1 em toda a página e
// usa og:title como fallback; o ID MLB do PDP confirma a mesma oferta.
const h1 = String(html).match(/<h1\b[^>]*class=["'][^"']*ui-pdp-title[^"']*["'][^>]*>([\s\S]*?)<\/h1>/i);
const og = String(html).match(/<meta\b[^>]*property=["']og:title["'][^>]*content=["']([^"']+)["'][^>]*>/i)
  || String(html).match(/<meta\b[^>]*content=["']([^"']+)["'][^>]*property=["']og:title["'][^>]*>/i);
const pageTitle = h1 ? clean(h1[1]) : (og ? clean(og[1]) : null);
const titleScore = similarity(pageTitle, original.product_title);
const urlMlb = (String(original.public_url || '').match(/MLB-?(\d+)/i) || [])[1] || null;
const pageMlb = (String(html).match(/(?:\/p\/|catalog\/reviews\/|bookmark\/add\/)(MLB\d+)/i) || [])[1] || null;
const sameMlb = Boolean(urlMlb && pageMlb && normalize(`MLB${urlMlb}`) === normalize(pageMlb));
if (!pageTitle || (titleScore < 0.60 && !sameMlb)) {
  return route({ rota: 'revisao_manual', outcome: 'review', httpStatus: statusCode, pageTitle, motivo: 'Título/ID do PDP não corresponde com segurança ao produto cadastrado' });
}

const priceBlock = findElementBy(html, /<div\b[^>]*\bid=["']price["'][^>]*>/i);
const unavailableText = /publica[cç][aã]o (est[aá] )?pausada|an[uú]ncio (foi )?(finalizado|encerrado|removido)|este produto est[aá] indispon[ií]vel|produto est[aá] indispon[ií]vel|n[aã]o encontramos essa p[aá]gina/i;
if (!priceBlock) {
  if (unavailableText.test(html)) {
    return route({ rota: 'indisponivel', outcome: 'unavailable', httpStatus: statusCode, pageTitle, motivo: 'Indisponibilidade explícita e ausência do bloco principal de preço' });
  }
  return route({ rota: 'revisao_manual', outcome: 'review', httpStatus: statusCode, pageTitle, motivo: 'Bloco #price do PDP não foi encontrado; preço não será adivinhado' });
}

const secondLineBlocks = [];
const secondLinePattern = /<div\b[^>]*class=["'][^"']*ui-pdp-price__second-line[^"']*["'][^>]*>/gi;
let secondLineMatch;
while ((secondLineMatch = secondLinePattern.exec(priceBlock))) {
  const block = extractElement(priceBlock, secondLineMatch.index);
  if (block) secondLineBlocks.push(block);
}
const actualBlock = secondLineBlocks.find((block) => /itemprop=["']offers["']/i.test(block)) || '';

if (!actualBlock || /R\$\s*\d[\d.,]*\s*(?:-|a|até)\s*R\$/i.test(clean(actualBlock))) {
  return route({ rota: 'revisao_manual', outcome: 'review', httpStatus: statusCode, pageTitle, motivo: 'Preço principal ausente ou apresentado como faixa/variação' });
}

const metaPrice = getMetaPrice(actualBlock);
const ariaPrice = getOfferAriaPrice(actualBlock);
if (!metaPrice && !ariaPrice) {
  return route({ rota: 'revisao_manual', outcome: 'review', httpStatus: statusCode, pageTitle, motivo: 'Preço principal sem meta itemprop=price e sem aria-label confirmável' });
}
if (metaPrice && ariaPrice && Math.abs(metaPrice - ariaPrice) > 0.01) {
  return route({ rota: 'revisao_manual', outcome: 'review', httpStatus: statusCode, pageTitle, detectedCurrentPrice: metaPrice, priceSource: 'pdp_meta_vs_aria_divergente', motivo: 'Meta de preço e rótulo visual do preço principal divergem' });
}

const precoNovo = metaPrice || ariaPrice;
let priceSource = metaPrice && ariaPrice
  ? 'pdp_meta_itemprop_price+aria_label_confirmados'
  : metaPrice ? 'pdp_meta_itemprop_price_confirmado' : 'pdp_aria_label_confirmado';
const couponApplied = /ui-pdp-price-breakdown[^>]*>[\s\S]*?com\s+cupom|com\s+cupom/i.test(actualBlock);
if (couponApplied) priceSource += '+cupom';

const oldTag = (priceBlock.match(/<s\b[^>]*class=["'][^"']*ui-pdp-price__original-value[^"']*["'][^>]*>[\s\S]*?<\/s>/i) || [])[0] || '';
let precoOriginalNovo = parseAriaMoney(attr(oldTag, 'aria-label')) || parseAndesMoney(oldTag);
if (!precoOriginalNovo || precoOriginalNovo <= precoNovo) precoOriginalNovo = null;

const precoAntigo = Number(original.current_price);
const highVariation = Number.isFinite(precoAntigo) && precoAntigo > 0 && (precoNovo > precoAntigo * 3 || precoNovo < precoAntigo / 3);
const strongPriceConfirmation = Boolean(metaPrice && ariaPrice);
if (highVariation && !strongPriceConfirmation) {
  return route({ rota: 'revisao_manual', outcome: 'review', httpStatus: statusCode, pageTitle, detectedCurrentPrice: precoNovo, detectedOriginalPrice: precoOriginalNovo, priceSource, motivo: 'Variação superior a 3x sem dupla confirmação no bloco principal' });
}
if (highVariation) priceSource += '+variacao_alta_confirmada';

const discountPercentNovo = precoOriginalNovo ? Math.floor((1 - precoNovo / precoOriginalNovo) * 100) : 0;
const precoAtualMudou = !Number.isFinite(precoAntigo) || Math.abs(precoNovo - precoAntigo) > 0.001;
const originalAntigo = original.original_price == null ? null : Number(original.original_price);
const precoOriginalMudou = (precoOriginalNovo == null && originalAntigo != null)
  || (precoOriginalNovo != null && (!Number.isFinite(originalAntigo) || Math.abs(precoOriginalNovo - originalAntigo) > 0.001));
const descontoAntigo = original.discount_percent == null ? 0 : Number(original.discount_percent);
const descontoMudou = !Number.isFinite(descontoAntigo) || Math.abs(discountPercentNovo - descontoAntigo) > 0.001;
const changed = precoAtualMudou || precoOriginalMudou || descontoMudou;
return route({
  rota: changed ? 'atualizar_preco' : 'sem_alteracao',
  outcome: changed ? 'updated' : 'unchanged',
  httpStatus: statusCode,
  pageTitle,
  precoNovo,
  precoOriginalNovo,
  discountPercentNovo,
  detectedCurrentPrice: precoNovo,
  detectedOriginalPrice: precoOriginalNovo,
  priceSource,
  motivo: null,
});

const stats = $getWorkflowStaticData('global');
const alertasAtingidosNoItem = $json.alertas_atingidos !== undefined && $json.alertas_atingidos !== null
  ? $json.alertas_atingidos
  : 0;
stats.precosAtualizados = (stats.precosAtualizados || 0) + 1;
stats.alertasAtingidos = (stats.alertasAtingidos || 0) + alertasAtingidosNoItem;
return [{ json: { ok: true } }];

const stats = $getWorkflowStaticData('global');
stats.semAlteracao = (stats.semAlteracao || 0) + 1;
return [{ json: { ok: true } }];

const stats = $getWorkflowStaticData('global');
stats.indisponiveis = (stats.indisponiveis || 0) + 1;
return [{ json: { ok: true } }];

const stats = $getWorkflowStaticData('global');
stats.falhasTemporarias = (stats.falhasTemporarias || 0) + 1;
return [{ json: { ok: true } }];

const stats = $getWorkflowStaticData('global');
stats.revisaoManual = (stats.revisaoManual || 0) + 1;
return [{ json: { ok: true } }];
